async function bookkeeping(){const d=await api('bookkeeping');return head('Bookkeeping',btn('Book a Demo','book-demo')+btn('Sync QuickBooks Online','sync',true))+`<section class="card"><h2>Numbers you can actually use · See Jobber Bookkeeping in action · More options · See What's New · Join for a chance to win a Ford F-150 Lariat · arrowLeft · arrowRight</h2><p>Your books, closed and explained by a real person every month.</p><div class="columns">${[['Dedicated bookkeeping','A dedicated bookkeeper closes your books every month.'],['Bring your books up to date','Catch-up bookkeeping to get your records tax-ready.'],['Know where your money stands','Monthly financial statements and clear breakdowns.'],['Automatic syncing with no double entry','Transactions flow from Jobber automatically.']].map(([h,p])=>`<div class="card"><h3>${h}</h3><p>${p}</p></div>`).join('')}</div></section><div class="stats">${[['Income',d.income_cents],['Expenses',d.expense_cents],['Net income',d.income_cents-d.expense_cents],['Tax',d.tax_cents]].map(([n,v])=>`<div class="card"><h3>${n}</h3><div class="number">${money(v)}</div></div>`).join('')}</div><p>QuickBooks Online · ${esc(d.integration?.status)} · Last sync ${esc(d.integration?.last_sync_at||'Not yet synced')}</p><h2>Reconciliation</h2>${table(d.ledger,[['Date',x=>esc(x.date?.slice(0,10))],['Name',x=>esc(x.name)],['Type',x=>esc(x.type)],['Category',x=>x.type==='expense'?`<button data-categorize="${x.id}">${esc(x.category)}</button>`:esc(x.category)],['Amount',x=>money(x.amount_cents)]])}`;}
async function insights(version=viewVersion){const [d,cs,rs,qs,js,ins,prof=[]]=await Promise.all(['dashboard','clients','requests','quotes','jobs','invoices','reports/profitability'].map(p=>api(p).catch(()=>[])));if(version!==viewVersion)return '';const d30=daysAgoIso(30),in30=r=>!r?.created_at||String(r.created_at).slice(0,10)>=d30,leads=cs.filter(c=>c.status==='lead'&&in30(c)).length,newReqs=rs.filter(in30).length,convQuotes=qs.filter(q=>['approved','converted'].includes(q.status)&&in30(q)).length,oneOff=js.filter(j=>j.job_type==='one_off'&&in30(j)).length,invoicedVal=sum(ins.filter(i=>!['draft','void'].includes(i.status)&&in30(i)),'total_cents'),openInvs=ins.filter(i=>!['draft','void','bad_debt','paid'].includes(i.status));return head('Insights',btn('Set Goal','insights-goal',true)+'<span class="muted">Set alert · Sep 1 – 30, 2026 · Jan 1, 2025 – Oct 28, 2026 · Oct 25 – Nov 21, 2026</span>')+`<div class="card"><h2>Overview <small>Last 30 days</small></h2><div class="stats">${[['New leads',leads],['New requests',newReqs],['Converted quotes',convQuotes],['New one-off jobs',oneOff],['Invoiced value',money(invoicedVal)]].map(([n,v])=>`<div class="card"><h3>${n}</h3><div class="number"><strong>${v}</strong></div></div>`).join('')}</div></div><div class="columns"><section class="card"><h2>Revenue <small>Last 12 months</small></h2><div class="number"><strong>${money(sum(ins.filter(i=>i.status==='paid'),'total_cents'))}</strong></div><p>Total revenue</p>${btn('Set Goal','insights-goal')}</section><section class="card"><h2>Profit and loss <small>Last 6 months</small></h2><p>Revenue vs Expenses</p>${btn('View Report','report/Projected%20income')}</section><section class="card"><h2>Cashflow <small>Last 30 days</small></h2><p>Cash in vs Cash out</p>${btn('View Report','report/Transactions')}</section><section class="card"><h2>Lead conversion · Lead funnel <small>Last 30 days</small></h2><p>Requests (${newReqs}) · Quotes (${qs.length}) · One-off jobs (${oneOff})</p></section><section class="card"><h2>Jobs <small>Scheduled job value</small></h2><div class="number"><strong>${money(sum(js,'total_cents'))}</strong></div><h3>Job profitability</h3>${table(js,[['Client',x=>esc(clientName(x.client_id))],['Job #',x=>'#'+(x.job_number||x.id)],['Total price',x=>money(x.total_cents)],['Labour cost',x=>money(prof.find(r=>r.id===x.id)?.labor_cost_cents||0)],['Expenses',x=>money(prof.find(r=>r.id===x.id)?.expense_cost_cents||0)],['Profit',x=>{const p=prof.find(r=>r.id===x.id);return money(p?.profit_cents??x.total_cents);}],['Profit margin',x=>{const p=prof.find(r=>r.id===x.id);return (p?.margin_percent??100)+'%';}]])}</section><section class="card"><h2>Receivables</h2><p>Outstanding balances: <strong>${money(d?.receivables_cents||sum(openInvs,'balance_due_cents'))}</strong></p>${table(openInvs,[['Client',x=>esc(clientName(x.client_id))],['Balance',x=>money(x.balance_due_cents)],['Late',x=>x.status==='past_due'?money(x.balance_due_cents):'$0.00']])}</section></div>`;}
