function genericTable(list){const keys=Object.keys(list[0]||{}).filter(k=>!k.endsWith('_json')&&!['organization_id','password_hash','portal_token'].includes(k)).slice(0,7);return table(list,keys.map(k=>[title(k),x=>esc(k.endsWith('_cents')?money(x[k]):x[k])]));}
async function collection(type,name,version=viewVersion){const fetched=await api(type);if(version!==viewVersion)return '';resource=type;rows=fetched;const editable=['catalog','custom-fields','automations','team','templates','integrations','checklists'].includes(type),keys=Object.keys(rows[0]||{}).filter(k=>!k.endsWith('_json')&&!['organization_id','password_hash','portal_token'].includes(k)).slice(0,7);return head(name,editable?btn('+ New','generic-new',true):'')+table(rows,[...keys.map(k=>[title(k),x=>esc(k.endsWith('_cents')?money(x[k]):x[k])]),...(editable?[['Actions',x=>`<button data-collection-edit="${type}:${x.id}">Edit</button><button data-delete-record="${type}:${x.id}">Delete</button>`]]:[])]);}
