let searchGeneration=0;async function globalSearch(){const q=$('.global-search').value.trim(),generation=++searchGeneration,version=++panelVersion;activeDetailKey='';if(!q){$('#overlay').innerHTML='<div class="popover" style="right:228px;width:320px"><h3>Search your workspace</h3><p class="muted">Find clients, requests, quotes, jobs, and invoices.</p></div>';return;}try{const results=await Promise.all(['clients','requests','quotes','jobs','invoices'].map(async type=>[type,await api(type+'?q='+encodeURIComponent(q))]));if(generation!==searchGeneration||version!==panelVersion)return;$('#overlay').innerHTML=`<div class="popover" style="right:210px;width:430px;max-height:70vh;overflow:auto"><h3>Search results</h3>${results.map(([type,list])=>`<h3>${title(type)}</h3>${list.slice(0,5).map(x=>`<button data-detail="${type}:${x.id}">${esc(x.display_name||x.title||x.subject)}</button>`).join('')||'<p class="muted">No results</p>'}`).join('')}</div>`;}catch(e){error(e);}}
