function csvDownload(data){const keys=Object.keys(data[0]||{}),csv=[keys,...data.map(row=>keys.map(k=>row[k]))].map(row=>row.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'})),a=document.createElement('a');a.href=url;a.download='report.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
